question.answer:
package main

import "fmt"

// Engine is fixed. It comes from the supplier, and nobody in the yard edits it.
type Engine struct {
	Power int
}

// Start is fixed. It reports the engine turning over.
func (e Engine) Start() string {
	return fmt.Sprintf("%d hp running", e.Power)
}

type Truck struct {
	Engine
	Load int
}

func describe(t Truck) string {
	return fmt.Sprintf("%d hp, %d t", t.Power, t.Load)
}

testcode.text:
t := Truck{Engine: Engine{Power: 300}, Load: 12}
fmt.Println(t.Start())
fmt.Println(describe(t))

