package main

// Announcer is fixed. It is the morning announcer's locked script.
type Announcer struct{}

// Greeting is fixed. It opens every morning message.
func (a Announcer) Greeting() string {
	return "Good morning"
}

// Announce is fixed. It reads the greeting, then the message.
func (a Announcer) Announce(msg string) string {
	return a.Greeting() + ". " + msg
}

// Station is fixed. Every announcer here works at the one station.
func (a Announcer) Station() string {
	return "Wellington Central"
}

type NightAnnouncer struct {
	Announcer
}

func (n NightAnnouncer) Greeting() string {
	return "Good evening"
}

func (n NightAnnouncer) Announce(msg string) string {
	return n.Greeting() + ". " + msg
}

