question.answer:
package main

import (
	"bufio"
	"errors"
	"io"
	"strings"
)

// ledger is fixed. It opens a block of text for reading.
func ledger(text string) *strings.Reader {
	return strings.NewReader(text)
}

type CountingReader struct {
	r io.Reader
	n int
}

func NewCountingReader(r io.Reader) *CountingReader {
	return &CountingReader{r: r}
}

func (c *CountingReader) Read(p []byte) (int, error) {
	n, err := c.r.Read(p)
	c.n += n
	return n, err
}

func (c *CountingReader) Count() int {
	return c.n
}

func lines(text string) ([]string, int, error) {
	counted := NewCountingReader(ledger(text))
	br := bufio.NewReader(counted)
	var out []string
	for {
		line, err := br.ReadString('\n')
		if err == nil {
			out = append(out, strings.TrimSuffix(line, "\n"))
			continue
		}
		if !errors.Is(err, io.EOF) {
			return nil, 0, err
		}
		if line != "" {
			out = append(out, line)
		}
		return out, counted.Count(), nil
	}
}
